		outcome := readable_outcome(candidate)
	}

	count(outcomes) == 1
	some result in outcomes
}

decision := {
	"disposition": "unresolved",
	"reasons": ["unknown"],
} if {
	evidence := object.get(input, "evidence", {})
	evidence["financial-evidence"] == "present"

	outcomes := {
		outcome |
		some risk in risk_values(input)
		some spend in spend_values(input)
		some country in country_values(input)
		candidate := object.union(
			input,
			{
				"vendor": object.union(
					object.get(input, "vendor", {}),
					{
						"riskScore": risk,
						"requestedSpend": spend,
						"countryRisk": country,
					},
				),
			},
		)
		outcome := readable_outcome(candidate)
	}

	count(outcomes) > 1
}

has_key(object, key) if {
	key in object.keys(object)
}

risk_values(value) := [value.vendor.riskScore] if {
	vendor := object.get(value, "vendor", {})
	has_key(vendor, "riskScore")
}

risk_values(value) := [0, 39, 40, 69, 70, 89, 90, 100] if {
	vendor := object.get(value, "vendor", {})
	not has_key(vendor, "riskScore")
}

spend_values(value) := [value.vendor.requestedSpend] if {
	vendor := object.get(value, "vendor", {})
	has_key(vendor, "requestedSpend")
}

spend_values(value) := [
	0,
	100000,
	500000,
	500000.01,
	2000000,
	2000000.01,
	10000000,
] if {
	vendor := object.get(value, "vendor", {})
	not has_key(vendor, "requestedSpend")
