	"disposition": "reject",
	"reasons": [],
} if {
	# D5. An omitted prior-enforcement status is treated as no.
	value.vendor.sanctionsStatus == "CLEAR"
	object.get(value.vendor, "priorEnforcement", "no") == "yes"
