	value.vendor.sanctionsStatus == "CLEAR"
	value.vendor.countryRisk == "LOW"
	value.vendor.riskScore < 40
	value.vendor.requestedSpend > 500000
	value.vendor.requestedSpend <= 2000000
	value.evidence["insurance-certificate"] == "present"
} else := {
	"disposition": "enhanced-review",
	"reasons": [],
} if {
	# D6b, certificate absent.
	value.vendor.sanctionsStatus == "CLEAR"
	value.vendor.countryRisk == "LOW"
	value.vendor.riskScore < 40
	value.vendor.requestedSpend > 500000
	value.vendor.requestedSpend <= 2000000
	value.evidence["insurance-certificate"] == "absent"
} else := {
	"disposition": "unresolved",
	"reasons": ["unknown"],
} if {
	# D6b, certificate availability unreported.
	value.vendor.sanctionsStatus == "CLEAR"
	value.vendor.countryRisk == "LOW"
	value.vendor.riskScore < 40
	value.vendor.requestedSpend > 500000
	value.vendor.requestedSpend <= 2000000
	not has_key(value.evidence, "insurance-certificate")
} else := {
	"disposition": "approve",
	"reasons": [],
} if {
	# D6c, as limited by O1.
	value.vendor.sanctionsStatus == "CLEAR"
	value.vendor.countryRisk == "LOW"
	value.vendor.riskScore >= 40
	value.vendor.riskScore < 70
	value.vendor.requestedSpend <= 100000
	object.get(value.vendor, "newVendor", "no") != "yes"
} else := {
	"disposition": "approve",
	"reasons": [],
} if {
	# D7.
	value.vendor.sanctionsStatus == "CLEAR"
	value.vendor.countryRisk == "MEDIUM"
	value.vendor.riskScore < 40
	value.vendor.requestedSpend <= 100000
} else := {
	# D8.
	"disposition": "review",
	"reasons": [],
} if {
	value.vendor.sanctionsStatus == "CLEAR"
